146	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
147	    @Override
148	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
149	        HttpHeaders headers = new HttpHeaders();
150	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
151	        normalizeOwnerFields(owner);
152	        // Enforce the pre-persistence policies that can reject the new owner outright.
153	        rejectDisallowedOwnerCreation(owner);
154	        // Resolve the owner's household membership: assign the deterministic 'householdId' (a pure
155	        // function of last name and postcode), reject a household duplicate unless the request
156	        // declares it shares the household, and record the household size. This runs before the
157	        // identity-key check so that check sees the owner's household id.
158	        boolean declaredHouseholdMember =
159	            applyHouseholdMembership(owner, Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold()));
160	        // Reject the create when the owner's whole derived identity key (normalized telephone,
161	        // email and household id) already matches an existing owner. This single rule subsumes the
162	        // former separate telephone, email and household duplicate checks.
163	        rejectWhenIdentityInUse(owner);
164	        // Flag the owner as a possible (soft) duplicate when, although not a hard duplicate, it
165	        // shares an existing owner's last name and postcode with a different telephone. A declared
166	        // household member is never flagged: it is a known member, not a suspected duplicate.
167	        assignPossibleDuplicate(owner, declaredHouseholdMember);
168	        // Assign the remaining create-time derived fields (namesake count, customer code,
169	        // membership number and bulk-signup warning), each fixed at creation time.
170	        assignDerivedFields(owner);
171	        this.clinicService.saveOwner(owner);
172	        // Emit an audit line for the successful create, carrying the owner id, customer code and
173	        // registration date so the create can be traced from the dedicated AUDIT log.
174	        AUDIT.info("Owner created: id={} customerCode={} registrationDate={}",
175	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate());
176	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
177	        headers.setLocation(UriComponentsBuilder.newInstance()
178	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
179	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
180	    }
