182	    /**
183	     * Enforces the pre-persistence policies that reject a newly mapped and normalized owner
184	     * outright, in order, before any derived fields are assigned or the owner is saved. Each
185	     * independent rule lives in its own {@code rejectWhen...} guard and is applied here in order, so
186	     * the sequence of create-time rejections stays readable and a new rule is added as one more
187	     * guard. Grouping the rules here keeps {@link #addOwner} focused on the household, derived-field
188	     * and persistence steps. The single duplicate rule that rejects an owner whose whole identity
189	     * key matches an existing one is applied separately in {@link #rejectWhenIdentityInUse}, after
190	     * the household id has been resolved, because that key includes the household id.
191	     *
192	     * @param owner the newly mapped and normalized owner being created
193	     */
194	    private void rejectDisallowedOwnerCreation(Owner owner) {
195	        rejectWhenDailyLimitReached(owner);
196	        rejectWhenCityAtCapacity(owner);
197	    }
198	
199	    /**
200	     * Applies the household-membership rules for a newly normalized owner being created. The
201	     * household id is a deterministic function of the owner's last name and postcode, so owners
202	     * with the same last name and postcode share it automatically; it is assigned to the new owner
203	     * here. Because the household is keyed on (last name, postcode), any existing owner with the
204	     * same last name and postcode is a member of the same household: a second such owner is rejected
205	     * as a household duplicate (409) unless the request declares it shares the household via
206	     * {@code sharesHousehold}, in which case it is created as a declared household member. The
207	     * owner's {@code householdSize} (the number of owners sharing the household after this create)
208	     * is recorded either way. The assigned household id is part of the owner's identity key, so it
209	     * is resolved here before {@link #rejectWhenIdentityInUse}.
210	     *
211	     * @param owner           the newly mapped and normalized owner being created
212	     * @param sharesHousehold whether the request declared that the owner shares an existing household
213	     * @return {@code true} if the owner joined an existing household as a declared member
214	     */
215	    private boolean applyHouseholdMembership(Owner owner, boolean sharesHousehold) {
216	        // Assign the deterministic household id (a pure function of last name and postcode) so every
217	        // owner with the same last name and postcode shares it automatically.
218	        owner.setHouseholdId(householdNormalizer.householdId(owner.getLastName(), owner.getPostcode()));
219	        // Identify any existing owners in the same household (same computed household id).
220	        List<Owner> householdMembers = sameHouseholdOwners(owner);
221	        // A second owner in an existing household is a household duplicate: reject it with 409 unless
222	        // the request declares it shares the household, in which case create it as a declared member.
223	        boolean declaredHouseholdMember = false;
224	        if (!householdMembers.isEmpty()) {
225	            if (!sharesHousehold) {
226	                throw new HouseholdDuplicateException(
227	                    "An owner in the household " + owner.getHouseholdId() + " already exists");
228	            }
229	            declaredHouseholdMember = true;
230	        }
231	        // Record the size of this owner's household after this create, fixed at creation time.
232	        owner.setHouseholdSize(householdMembers.size() + 1);
233	        return declaredHouseholdMember;
234	    }
235	
236	    /**
237	     * Assigns the create-time derived fields of a newly normalized owner whose household membership
238	     * has already been resolved: the namesake count, the per-city customer code, the membership
239	     * number derived from that customer code and the registration year, and the bulk-signup warning
240	     * flag. Each value is fixed at creation time and is independent of the others. Grouping them
241	     * here keeps {@link #addOwner} focused on the high-level create sequence.
242	     *
243	     * @param owner the owner being created, already normalized and with its household resolved
244	     */
245	    private void assignDerivedFields(Owner owner) {
246	        // Record how many existing owners already share this owner's first and last name
247	        // (compared case-insensitively) before this create, fixed at creation time.
248	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
249	        // Assign the customer code '<REGION>-<HASH8>' from the region derived from the postcode
250	        // and an 8-hex-character hash of the normalized telephone and last name, fixed at creation
251	        // time.
252	        owner.setCustomerCode(customerCode(owner));
253	        // Assign the membership number '<customerCode>-M<YY>', where YY is the last two digits
254	        // of the registration date's year (e.g. 'NSW-A1B2C3D4-M26'), fixed at creation time.
255	        owner.setMembershipNumber(membershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
256	        // Flag the create when more than 80 owners have already been created on this owner's
257	        // (adjusted business-day) registration date, fixed at creation time.
258	        owner.setBulkSignupWarning(
259	            countOwnersRegisteredOn(owner.getRegistrationDate()) > BULK_SIGNUP_WARNING_THRESHOLD);
260	    }
