262	    /**
263	     * Rejects creating an owner whose whole derived identity key already matches an existing owner,
264	     * with 409 Conflict. The identity key ({@link Owner#getIdentityKey()}) joins the normalized
265	     * telephone, the email (or empty) and the household id (or empty), so this single rule replaces
266	     * the former separate telephone, email and household duplicate checks: two owners collide only
267	     * when their whole keys are equal, and members of one household with different telephones have
268	     * different keys and are both allowed.
269	     *
270	     * @param owner the owner being created, already normalized and with its household resolved
271	     */
272	    private void rejectWhenIdentityInUse(Owner owner) {
273	        String identityKey = owner.getIdentityKey();
274	        boolean inUse = existingOwners()
275	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
276	        if (inUse) {
277	            throw new DuplicateIdentityException(
278	                "An owner with identity key " + identityKey + " already exists");
279	        }
280	    }
281	
282	    /**
283	     * Assigns the soft-duplicate flags for a newly normalized owner that has already passed the hard
284	     * duplicate (identity-key) check. When an existing owner shares this owner's last name (compared
285	     * case-insensitively) and postcode but carries a different (normalized) telephone, the new owner
286	     * is still created but flagged as a possible duplicate: {@code possibleDuplicate} is set true and
287	     * {@code possibleDuplicateOf} to the matching owner's id (the lowest such id when several match).
288	     * Otherwise {@code possibleDuplicate} is false and {@code possibleDuplicateOf} is left absent.
289	     * A postcode is required on both sides for a match, so an owner without a postcode is never a
290	     * possible duplicate. A declared household member is never flagged: it is a known member of the
291	     * household, not a suspected duplicate. Both values are fixed at creation time.
292	     *
293	     * @param owner                   the owner being created, already normalized and confirmed not a
294	     *                                hard duplicate
295	     * @param declaredHouseholdMember whether the owner joined an existing household as a declared
296	     *                                member
297	     */
298	    private void assignPossibleDuplicate(Owner owner, boolean declaredHouseholdMember) {
299	        Integer matchId = declaredHouseholdMember || owner.getPostcode() == null ? null : existingOwners()
300	            .filter(existing -> isPossibleDuplicateOf(existing, owner))
301	            .map(Owner::getId)
302	            .min(Integer::compareTo)
303	            .orElse(null);
304	        owner.setPossibleDuplicate(matchId != null);
305	        owner.setPossibleDuplicateOf(matchId);
306	    }
307	
308	    /**
309	     * Tests whether an existing owner makes the owner being created a possible (soft) duplicate: the
310	     * two share a postcode (required on both sides, so an owner without a postcode never matches) and
311	     * a last name (compared case-insensitively) but carry different (normalized) telephones. A match
312	     * flags the new owner as a possible duplicate of the existing one without rejecting the create.
313	     *
314	     * @param existing an existing owner to compare against
315	     * @param owner    the owner being created
316	     * @return {@code true} if the existing owner makes the new owner a possible duplicate
317	     */
318	    private boolean isPossibleDuplicateOf(Owner existing, Owner owner) {
319	        return existing.getPostcode() != null
320	            && existing.getPostcode().equals(owner.getPostcode())
321	            && existing.getLastName() != null
322	            && existing.getLastName().equalsIgnoreCase(owner.getLastName())
323	            && existing.getTelephone() != null
324	            && !existing.getTelephone().equals(owner.getTelephone());
325	    }
