327	    /**
328	     * Rejects creating an owner once {@link #MAX_OWNERS_PER_DAY} or more owners already carry this
329	     * owner's adjusted business-day registration date, with 429 Too Many Requests.
330	     *
331	     * @param owner the owner being created
332	     */
333	    private void rejectWhenDailyLimitReached(Owner owner) {
334	        if (countOwnersRegisteredOn(owner.getRegistrationDate()) >= MAX_OWNERS_PER_DAY) {
335	            throw new DailyOwnerLimitExceededException(
336	                "The maximum number of owners that may be created today has already been reached");
337	        }
338	    }
