340	    /**
341	     * Rejects creating an owner when the owner's city already contains {@link #MAX_OWNERS_PER_CITY}
342	     * or more owners, with 409 Conflict.
343	     *
344	     * @param owner the owner being created
345	     */
346	    private void rejectWhenCityAtCapacity(Owner owner) {
347	        if (countOwnersInCity(owner.getCity()) >= MAX_OWNERS_PER_CITY) {
348	            throw new CityCapacityExceededException(
349	                "The city " + owner.getCity() + " already contains the maximum number of owners");
350	        }
351	    }
