353	    /**
354	     * Canonicalizes the fields of a newly mapped owner on create, in place, so each value is
355	     * persisted and returned in its canonical form. The address is normalized (trimmed, whitespace
356	     * collapsed, upper-cased and common abbreviations expanded, rejecting a value blank after
357	     * normalization with 400), the telephone is normalized to E.164 (rejecting an unformattable
358	     * value with 400), the email is lower-cased, and a missing registration date defaults to the
359	     * server's current date. Canonicalising the address here, before the household checks read it,
360	     * ensures duplicate detection and the shared household id both compare the normalized form.
361	     * Centralising these per-field canonicalizations here keeps {@link #addOwner} focused on the
362	     * duplicate, household and customer-code rules.
363	     *
364	     * @param owner the newly mapped owner to canonicalize
365	     */
366	    private void normalizeOwnerFields(Owner owner) {
367	        // Normalize the address on create so it is stored and returned in canonical form and every
368	        // later comparison (household duplicate detection and the shared household id) uses it.
369	        // A value that is blank after normalization is rejected with 400.
370	        owner.setAddress(addressNormalizer.normalize(owner.getAddress()));
371	        // Normalize the telephone on create so it is stored and returned in canonical E.164 form.
372	        // A value that cannot form a valid E.164 number, or whose national-number length is wrong
373	        // for its country code (+61 => 9 national digits, +1 => 10), is rejected with 400.
374	        owner.setTelephone(telephoneNormalizer.normalizeAndValidate(owner.getTelephone()));
375	        // Store the (already syntactically validated) email lower-cased so it is persisted and
376	        // returned in canonical form. A missing email is left untouched.
377	        owner.setEmail(emailNormalizer.normalize(owner.getEmail()));
378	        // Validate the optional postcode against the fixed range for the city's region. A postcode
379	        // is checked only when present (it is optional); one out of range for the city's region is
380	        // rejected with 400. A city with no known region accepts any 4-digit postcode. The stored
381	        // value is left unchanged.
382	        PostcodeValidator.validate(owner.getCity(), owner.getPostcode());
383	        // Reject a supplied registration date that is later than the server's current date with
384	        // 400, before any defaulting or business-day adjustment, so a future date is never
385	        // persisted regardless of how the roll-forward would move it.
386	        rejectFutureRegistrationDate(owner.getRegistrationDate());
387	        // Default the registration date to the server's current date when the client did not
388	        // supply one, then roll the effective date forward to a business day so a Saturday or
389	        // Sunday (whether supplied or defaulted) becomes the following Monday. The adjusted date
390	        // is persisted and returned in ISO 'YYYY-MM-DD' form and is the value every registration-
391	        // date-derived field (such as the membership number's year segment) and the per-day
392	        // create-limit are computed from.
393	        java.time.LocalDate effectiveDate = owner.getRegistrationDate() == null
394	            ? java.time.LocalDate.now() : owner.getRegistrationDate();
395	        owner.setRegistrationDate(toBusinessDay(effectiveDate));
396	    }
397	
398	    /**
399	     * Rejects a supplied registration date that is later than the server's current date with a
400	     * 400 Bad Request. A missing registration date (defaulted to the server date later) is
401	     * accepted, and a date on or before today is left for the normal defaulting and business-day
402	     * adjustment.
403	     *
404	     * @param registrationDate the client-supplied registration date, or {@code null} when absent
405	     */
406	    private void rejectFutureRegistrationDate(java.time.LocalDate registrationDate) {
407	        if (registrationDate != null && registrationDate.isAfter(java.time.LocalDate.now())) {
408	            throw new InvalidRegistrationDateException(
409	                "The supplied registration date " + registrationDate + " is later than the current date");
410	        }
411	    }
412	
413	    /**
414	     * Rolls a registration date forward to a business day: a Saturday or Sunday advances to the
415	     * following Monday, while a weekday is returned unchanged. Applied to the effective
416	     * registration date (whether supplied in the request or defaulted to the server date) so the
417	     * persisted registration date, every value derived from it and the per-day create-limit all
418	     * use the adjusted business day.
419	     *
420	     * @param date the effective registration date
421	     * @return the same date if it is a weekday, otherwise the following Monday
422	     */
423	    private java.time.LocalDate toBusinessDay(java.time.LocalDate date) {
424	        java.time.LocalDate adjusted = date;
425	        while (adjusted.getDayOfWeek() == java.time.DayOfWeek.SATURDAY
426	            || adjusted.getDayOfWeek() == java.time.DayOfWeek.SUNDAY) {
427	            adjusted = adjusted.plusDays(1);
428	        }
429	        return adjusted;
430	    }
