432	    /**
433	     * Builds the customer code '<REGION>-<HASH8>' for a newly created owner, where REGION is the
434	     * region derived from the owner's postcode (falling back to the city, via
435	     * {@link LocalityResolver}) and HASH8 is the first 8 upper-case hex characters of the SHA-256
436	     * digest over the owner's normalized telephone concatenated with the last name (e.g.
437	     * 'NSW-A1B2C3D4'). The identity carries no sequence number, so it is a pure function of the
438	     * owner's region and identity fields.
439	     *
440	     * @param owner the owner being created, already normalized
441	     * @return the formatted customer code
442	     */
443	    private String customerCode(Owner owner) {
444	        String region = LocalityResolver.resolve(owner.getCity(), owner.getPostcode());
445	        String hash8 = Sha256Hex.upperHexPrefix(owner.getTelephone() + owner.getLastName(), 8);
446	        return region + "-" + hash8;
447	    }
