449	    /**
450	     * Streams the existing owners that the create-time rules match a new owner against. Every
451	     * duplicate, quota and derived-field rule scans this same set of owners and differs only in the
452	     * predicate it applies, so fetching them is centralized here to keep each rule focused on its
453	     * own matching criterion rather than on how the existing owners are retrieved.
454	     *
455	     * @return a stream over all existing owners
456	     */
457	    private Stream<Owner> existingOwners() {
458	        return this.clinicService.findAllOwners().stream();
459	    }
460	
461	    /**
462	     * Counts the existing owners located in the given city, compared case-insensitively. Used to
463	     * fix the per-city sequence of an owner's customer code at creation time.
464	     *
465	     * @param city the city of the owner being created
466	     * @return the number of existing owners in a matching city
467	     */
468	    private int countOwnersInCity(String city) {
469	        return (int) existingOwners()
470	            .filter(existing -> existing.getCity() != null
471	                && existing.getCity().equalsIgnoreCase(city))
472	            .count();
473	    }
474	
475	    /**
476	     * Counts the existing owners whose registration date is the given adjusted business day. Used
477	     * to enforce the per-day cap that rejects creating an owner once {@link #MAX_OWNERS_PER_DAY}
478	     * owners already carry that business day as their registration date.
479	     *
480	     * @param date the adjusted business-day registration date to match
481	     * @return the number of existing owners registered on that date
482	     */
483	    private int countOwnersRegisteredOn(java.time.LocalDate date) {
484	        return (int) existingOwners()
485	            .filter(existing -> date.equals(existing.getRegistrationDate()))
486	            .count();
487	    }
488	
489	    /**
490	     * Builds the membership number '<customerCode>-M<YY>' for a newly created owner, where YY is
491	     * the last two digits of the registration date's year (e.g. 'NSW-A1B2C3D4-M26').
492	     *
493	     * @param customerCode     the owner's customer code
494	     * @param registrationDate the owner's registration date
495	     * @return the formatted membership number
496	     */
497	    private String membershipNumber(String customerCode, java.time.LocalDate registrationDate) {
498	        return String.format("%s-M%02d", customerCode, registrationDate.getYear() % 100);
499	    }
500	
501	    /**
502	     * Returns the existing owners in the given owner's household, i.e. those sharing its
503	     * deterministic household id (the same last name and postcode). The id is computed via
504	     * {@link HouseholdNormalizer} so that last names differing only in letter case or in incidental
505	     * whitespace are treated as the same household. Centralising how "the same household" is matched
506	     * here keeps that definition in one place for every caller.
507	     *
508	     * @param owner the owner being created, with its household id already assigned
509	     * @return the existing owners in the owner's household (possibly empty)
510	     */
511	    private List<Owner> sameHouseholdOwners(Owner owner) {
512	        String householdId = owner.getHouseholdId();
513	        return existingOwners()
514	            .filter(existing -> householdId.equals(
515	                householdNormalizer.householdId(existing.getLastName(), existing.getPostcode())))
516	            .toList();
517	    }
518	
519	    /**
520	     * Counts the existing owners who share the given first and last name, compared
521	     * case-insensitively. Used to fix an owner's namesake count at creation time.
522	     *
523	     * @param firstName the first name of the owner being created
524	     * @param lastName  the last name of the owner being created
525	     * @return the number of existing owners with a matching first and last name
526	     */
527	    private int countNamesakes(String firstName, String lastName) {
528	        return (int) existingOwners()
529	            .filter(existing -> existing.getFirstName() != null
530	                && existing.getFirstName().equalsIgnoreCase(firstName)
531	                && existing.getLastName() != null
532	                && existing.getLastName().equalsIgnoreCase(lastName))
533	            .count();
534	    }
